mapper.select:
SELECT COUNT(1) FROM LOADMATERIAL  WHERE 1=1
AND MOID=#{moid,jdbcType=VARCHAR}
AND SLOT= #{slot,jdbcType=VARCHAR}
AND EQPNAME=#{eqpname,jdbcType=VARCHAR}
AND (TASKNAME IS NULL OR TASKNAME='ComfirmParts' OR TASKNAME='LoadFeeders')
AND PN =#{pn,jdbcType=VARCHAR}

        SELECT #{upn,jdbcType=VARCHAR} UPN, SLOT,EQPNAME
  FROM Loadinglistcontent
 WHERE pn = #{pn,jdbcType=VARCHAR}
   AND llid = #{llid,jdbcType=VARCHAR}
UNION
SELECT #{upn,jdbcType=VARCHAR} UPN,SLOT,EQPNAME
  FROM Loadinglistcontent
 WHERE ALTERNATEPN = #{pn,jdbcType=VARCHAR}
   AND llid = #{llid,jdbcType=VARCHAR}

SELECT COUNT(1) from UPN U,PRP_LOT PR,RMM_WOMATERIALLIST RW,PARTNUMBER PA
                WHERE U.PNID = PA.PNID AND PA.PN=RW.PN AND PR.WORKORDERID=RW.WORKORDERID
                AND PR.LOTNAME=#{lotName}
                AND U.UPNNAME=#{upnName}

SELECT COUNT(1) FROM PRP_LOT PR1,PRP_LOT PR2,RMM_WOMATERIALLIST RW
                WHERE PR2.PRODUCTPN=RW.PN
                 AND PR1.WORKORDERID=RW.WORKORDERID
                 AND PR1.LOTNAME=#{lotName1}
                 AND PR2.LOTNAME=#{lotName2}


SELECT LINEID FROM (
SELECT LINEID FROM A03_SM_USED_LOT
WHERE UPNNAME = #{upn}
AND LINEID = #{lineId}
ORDER BY USEDTIME DESC
) WHERE ROWNUM = 1
